begin;create extension if not exists pgtap with schema extensions;set local search_path=public,extensions;select no_plan();
-- FIXTURE_BEGIN: synthetic metadata and service captures; byte transport is tested separately.
insert into auth.users(id,email,raw_user_meta_data) values('db470000-0000-4000-8000-000000000001','release-source-admin@example.test','{}'),('db470000-0000-4000-8000-000000000002','release-source-dvm@example.test','{}');
update public.profiles set is_active = true where id in ('db470000-0000-4000-8000-000000000001','db470000-0000-4000-8000-000000000002');
insert into public.user_roles (user_id, role) values ('db470000-0000-4000-8000-000000000001','STAFF'),('db470000-0000-4000-8000-000000000002','STAFF');

insert into user_roles(user_id,role) values('db470000-0000-4000-8000-000000000001','ADMIN'),('db470000-0000-4000-8000-000000000002','DVM');
create temp table fx(k text primary key,id uuid);grant all on fx to authenticated,service_role;
create temp table data(k text primary key,v jsonb);grant all on data to authenticated,service_role;
set local role authenticated;select set_config('request.jwt.claims','{"sub":"db470000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into fx select 'client',id from save_client(auth.uid(),null,null,'Release','Source','+13035550177','release-source@example.test','EMAIL',null,null);
insert into fx select 'pet',id from save_patient(null,(select id from fx where k='client'),null,'Source dog','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into fx select 'other',id from save_patient(null,(select id from fx where k='client'),null,'Other dog','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into fx select k,gen_random_uuid() from unnest(array['doc','corrected-doc','external-doc','replacement-doc','plain-doc','mapping','snapshot','order','source','order-review','report','corrected-report','receipt','corrected-receipt','external-receipt','replacement-receipt','record','replacement-record','legacy-release','release','ack','external-ack']) k;
reset role;
insert into ezyvet_import_snapshots(id,source_origin,source_site_uid,resource,external_id,payload,payload_hash,first_seen_by) values((select id from fx where k='snapshot'),'https://api.trial.ezyvet.com','release-test-site','animal','77','{"id":77}','synthetic-hash','db470000-0000-4000-8000-000000000001');
insert into ezyvet_record_links(id,request_id,request_hash,source_origin,source_site_uid,resource,external_id,snapshot_id,head_version,client_id,pet_id,local_version,action,reason,approved_by) values((select id from fx where k='mapping'),gen_random_uuid(),'mapping-hash','https://api.trial.ezyvet.com','release-test-site','animal','77',(select id from fx where k='snapshot'),1,(select id from fx where k='client'),(select id from fx where k='pet'),1,'link','PRIVATE mapping reason','db470000-0000-4000-8000-000000000001');
create function pg_temp.ready_doc(p_id uuid) returns void language plpgsql security definer set search_path=public as $$declare d public.patient_documents;begin
 d:=prepare_patient_document(p_id,(select id from fx where k='pet'),null,'synthetic.pdf','application/pdf',12,'medical_record','Synthetic source original',null,'client_shareable');
 insert into storage.objects(bucket_id,name,metadata) values('patient-documents',d.file_path,'{"size":12,"mimetype":"application/pdf"}');perform finalize_patient_document(p_id);
end $$;
select pg_temp.ready_doc(id) from fx where k in ('doc','corrected-doc','external-doc','replacement-doc','plain-doc');
insert into record_release_policy(id,enabled,accepted_by,accepted_at,acceptance_reference,accepted_schema_version) values(true,true,'Synthetic rollback reviewer',now(),'TEST ONLY',4);
set local role authenticated;
insert into data values('received',to_jsonb(now()));
insert into data select 'legacy-selection',jsonb_build_object('document_ids',jsonb_build_array((select id from fx where k='doc')));
insert into data select 'legacy-preview',preview_record_release_v4((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','release-source@example.test',(select v from data where k='legacy-selection'));
insert into data select 'legacy-row',to_jsonb(confirm_record_release((select id from fx where k='legacy-release'),(select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','release-source@example.test',(select v from data where k='legacy-selection'),(select v->'snapshot' from data where k='legacy-preview'),(select v->>'source_hash' from data where k='legacy-preview'),true));
select save_patient_lab_order((select id from fx where k='order'),(select id from fx where k='pet'),null,'{"test_name":"Synthetic lab","status":"planned","notes":"PRIVATE native notes"}','');
select review_lab_source_account((select id from fx where k='source'),'Synthetic Lab','Reviewed account','Training','PRIVATE account review');
select review_lab_order_source((select id from fx where k='order-review'),(select id from fx where k='order'),(select id from fx where k='pet'),1,(select id from fx where k='source'),'patient-77','order-77',null,'PRIVATE source review',true);
insert into data select 'receipt',to_jsonb(stage_lab_report_receipt((select id from fx where k='receipt'),(select id from fx where k='source'),(select id from fx where k='doc'),2,'patient-77','order-77','report-77',now()));
insert into data select 'corrected-receipt',to_jsonb(stage_lab_report_receipt((select id from fx where k='corrected-receipt'),(select id from fx where k='source'),(select id from fx where k='corrected-doc'),2,'patient-77','order-77','report-78',now()));
insert into data select 'external-receipt',to_jsonb(stage_external_record_receipt((select id from fx where k='external-receipt'),(select id from fx where k='mapping'),1,(select id from fx where k='external-doc'),2,'export-77',now(),null,'PRIVATE external review'));
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into data select 'capture',to_jsonb(capture_lab_report_bytes((select id from fx where k='receipt'),'db470000-0000-4000-8000-000000000001',(select v->>'receipt_hash' from data where k='receipt'),2,repeat('a',64),12,'application/pdf'));
insert into data select 'corrected-capture',to_jsonb(capture_lab_report_bytes((select id from fx where k='corrected-receipt'),'db470000-0000-4000-8000-000000000001',(select v->>'receipt_hash' from data where k='corrected-receipt'),2,repeat('b',64),12,'application/pdf'));
insert into data select 'external-capture',to_jsonb(capture_external_record_bytes((select id from fx where k='external-receipt'),'db470000-0000-4000-8000-000000000001',(select v->>'receipt_hash' from data where k='external-receipt'),2,repeat('c',64),12,'application/pdf'));
set local role authenticated;select set_config('request.jwt.claims','{"sub":"db470000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select link_lab_report_version((select id from fx where k='report'),(select id from fx where k='receipt'),(select v->>'receipt_hash' from data where k='receipt'),(select v->>'capture_hash' from data where k='capture'),(select id from fx where k='order'),(select id from fx where k='pet'),1,(select id from fx where k='order-review'),null,'original','PRIVATE link review',true);
select approve_external_record_import((select id from fx where k='record'),(select id from fx where k='external-receipt'),(select v->>'receipt_hash' from data where k='external-receipt'),(select v->>'capture_hash' from data where k='external-capture'),true);
insert into data select 'selection',jsonb_build_object('lab_report_ids',jsonb_build_array((select id from fx where k='report')),'external_record_ids',jsonb_build_array((select id from fx where k='record')),'document_ids',jsonb_build_array((select id from fx where k='doc'),(select id from fx where k='external-doc')));
-- FIXTURE_END
select throws_ok($$select preview_record_release_v5((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','release-source@example.test',jsonb_build_object('lab_report_ids',jsonb_build_array('abcdef00-0000-4000-8000-000000000001','ABCDEF00-0000-4000-8000-000000000001')))$$,'23514','Unique source IDs required','Case variants of same UUID rejected before lookup');
select is((select count(*)::integer from jsonb_each(select_all_record_release_sources_v5((select id from fx where k='other'))->'selection') where jsonb_typeof(value)='array'),14,'Sparse patient select-all exposes all fourteen array families');
insert into data select 'preview',preview_record_release_v5((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','release-source@example.test',(select v from data where k='selection'));
select is((select v#>>'{snapshot,schema_version}' from data where k='preview'),'5','Explicit new preview emits schema5');
select is((select v#>>'{snapshot,lab_reports,0,content_sha256}' from data where k='preview'),repeat('a',64),'Captured lab byte digest frozen');
select is((select v#>>'{snapshot,external_records,0,source,source_site_uid}' from data where k='preview'),'release-test-site','External source site frozen');
select is((select jsonb_array_length(v#>'{snapshot,lab_reports,0,acknowledgments}') from data where k='preview'),0,'Import does not manufacture acknowledgment');
select ok(not (select (v->'snapshot')::text from data where k='preview') like '%PRIVATE%','No private source or clinical reasons leak into provenance');
select is((select jsonb_array_length(a->'provenance_captures') from data cross join lateral jsonb_array_elements(v#>'{snapshot,attachments}') a where k='preview' and a->>'id'=(select id::text from fx where k='doc')),1,'Original has exact selected-version proof');
select is(public.read_record_release((select id from fx where k='legacy-release'))->>'eligible','false','New association invalidates old delivery');
select is((confirm_record_release((select id from fx where k='legacy-release'),(select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','release-source@example.test',(select v from data where k='legacy-selection'),(select v->'snapshot' from data where k='legacy-preview'),(select v->>'source_hash' from data where k='legacy-preview'),true)).snapshot,(select v->'snapshot' from data where k='legacy-row'),'Old exact receipt recovers frozen original after association');
select throws_ok($$select confirm_record_release(gen_random_uuid(),(select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','release-source@example.test',(select v from data where k='legacy-selection'),(select v->'snapshot' from data where k='legacy-preview'),(select v->>'source_hash' from data where k='legacy-preview'),true)$$,'23514',null,'New legacy confirmation cannot omit provenance');
select throws_ok($$select preview_record_release_v5((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','release-source@example.test',(select v-'lab_report_ids' from data where k='selection'))$$,'23514',null,'Document-only downgrade rejected');
select throws_ok($$select preview_record_release_v5((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','release-source@example.test',(select v-'document_ids' from data where k='selection'))$$,'23514',null,'Original selection is explicit');
select throws_ok($$select preview_record_release_v5((select id from fx where k='other'),(select id from fx where k='client'),'EMAIL','release-source@example.test',(select v from data where k='selection'))$$,'23514',null,'Cross-patient sources rejected');
select throws_ok($$select confirm_record_release((select id from fx where k='release'),(select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','release-source@example.test',(select v from data where k='selection'),(select v->'snapshot' from data where k='preview'),(select v->>'source_hash' from data where k='preview'),true)$$,'42501',null,'Schema4 acceptance cannot commission schema5');
select is(list_record_release_sources_v5((select id from fx where k='pet'))->>'policy_v5_accepted','false','Discovery exposes independent acceptance');
select is(jsonb_array_length(list_record_release_sources_v5((select id from fx where k='pet'))->'lab_report_ids'),1,'Verified lab version discoverable');
select is(jsonb_array_length(select_all_record_release_sources_v5((select id from fx where k='pet'))#>'{selection,external_record_ids}'),1,'Select-all includes approved external version');
reset role;update record_release_policy set accepted_schema_version=5;
set local role authenticated;
select lives_ok($$select confirm_record_release((select id from fx where k='release'),(select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','release-source@example.test',(select v from data where k='selection'),(select v->'snapshot' from data where k='preview'),(select v->>'source_hash' from data where k='preview'),true)$$,'Exact schema5 confirmed under rollback-only acceptance');
select is(read_record_release((select id from fx where k='release'))->>'eligible','true','Unchanged confirmed schema5 remains eligible');
select set_config('request.jwt.claims','{"sub":"db470000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select acknowledge_lab_report((select id from fx where k='ack'),(select id from fx where k='report'),(select id from fx where k='pet'),(select v->>'capture_hash' from data where k='capture'),2,true);
select is(read_record_release((select id from fx where k='release'))->>'eligible','false','New exact-version DVM acknowledgment invalidates reviewed package');
select set_config('request.jwt.claims','{"sub":"db470000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(jsonb_array_length(preview_record_release_v5((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','release-source@example.test',(select v from data where k='selection'))#>'{snapshot,lab_reports,0,acknowledgments}'),1,'Fresh preview discloses independent acknowledgment');
select link_lab_report_version((select id from fx where k='corrected-report'),(select id from fx where k='corrected-receipt'),(select v->>'receipt_hash' from data where k='corrected-receipt'),(select v->>'capture_hash' from data where k='corrected-capture'),(select id from fx where k='order'),(select id from fx where k='pet'),1,(select id from fx where k='order-review'),(select id from fx where k='report'),'corrected','PRIVATE correction',true);
select is(preview_record_release_v5((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','release-source@example.test',(select v from data where k='selection'))#>>'{snapshot,lab_reports,0,historical}','true','Old report remains explicitly historical and selectable');
select ok(not has_function_privilege('service_role','release_preview_v5_internal(uuid,uuid,text,text,jsonb)','EXECUTE'),'Internal snapshot cannot be called directly by service');
select ok(not has_function_privilege('anon','preview_record_release_v5(uuid,uuid,text,text,jsonb)','EXECUTE'),'Anonymous caller cannot preview chart sources');
-- Missing pre4700 events cannot keep legacy delivery eligible.
reset role;set local session_replication_role=replica;delete from record_release_events where release_id=(select id from fx where k='legacy-release');set local session_replication_role=origin;
set local role authenticated;
select is(read_record_release((select id from fx where k='legacy-release'))->>'eligible','false','Read-time guard catches provenance approved before new triggers existed');
select is((select snapshot from record_releases where id=(select id from fx where k='legacy-release')),(select v->'snapshot' from data where k='legacy-row'),'Preexisting legacy snapshot remains unchanged');
-- A same-identity source review must be visible in the new artifact/hash.
insert into data select 'before-source-review',preview_record_release_v5((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','release-source@example.test',(select v from data where k='selection'));
insert into fx values('new-source-review',gen_random_uuid());
select review_lab_order_source((select id from fx where k='new-source-review'),(select id from fx where k='order'),(select id from fx where k='pet'),1,(select id from fx where k='source'),'patient-77','order-77',(select id from fx where k='order-review'),'Same identity rechecked',true);
select is(preview_record_release_v5((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','release-source@example.test',(select v from data where k='selection'))#>>'{snapshot,lab_reports,0,latest_source_review_id}',(select id::text from fx where k='new-source-review'),'Same-identity later review is explicitly frozen');
select isnt(preview_record_release_v5((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','release-source@example.test',(select v from data where k='selection'))->>'source_hash',(select v->>'source_hash' from data where k='before-source-review'),'Later source review changes reviewed hash');
select review_lab_order_source(gen_random_uuid(),(select id from fx where k='order'),(select id from fx where k='pet'),1,(select id from fx where k='source'),'different-patient','order-77',(select id from fx where k='new-source-review'),'Current identity changed',true);
select throws_ok($$select preview_record_release_v5((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','release-source@example.test',(select v from data where k='selection'))$$,'23514',null,'Changed current source identity blocks fresh release');
select is(jsonb_array_length(list_record_release_sources_v5((select id from fx where k='pet'))->'lab_report_ids'),0,'Discovery excludes currently mismatched source identities');
-- A schema5 ordinary document cannot bypass a later approved association either.
insert into fx select k,gen_random_uuid() from unnest(array['association-release','association-receipt','association-record']) k;
insert into data select 'association-selection',jsonb_build_object('document_ids',jsonb_build_array((select id from fx where k='plain-doc')));
insert into data select 'association-preview',preview_record_release_v5((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','release-source@example.test',(select v from data where k='association-selection'));
select confirm_record_release((select id from fx where k='association-release'),(select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','release-source@example.test',(select v from data where k='association-selection'),(select v->'snapshot' from data where k='association-preview'),(select v->>'source_hash' from data where k='association-preview'),true);
insert into data select 'association-receipt',to_jsonb(stage_external_record_receipt((select id from fx where k='association-receipt'),(select id from fx where k='mapping'),1,(select id from fx where k='plain-doc'),2,'new-association',now(),null,'Synthetic new association'));
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into data select 'association-capture',to_jsonb(capture_external_record_bytes((select id from fx where k='association-receipt'),'db470000-0000-4000-8000-000000000001',(select v->>'receipt_hash' from data where k='association-receipt'),2,repeat('e',64),12,'application/pdf'));
set local role authenticated;select set_config('request.jwt.claims','{"sub":"db470000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select approve_external_record_import((select id from fx where k='association-record'),(select id from fx where k='association-receipt'),(select v->>'receipt_hash' from data where k='association-receipt'),(select v->>'capture_hash' from data where k='association-capture'),true);
select is(read_record_release((select id from fx where k='association-release'))->>'eligible','false','New association invalidates schema5 document-only release');
select throws_ok($$select preview_record_release_v5((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','release-source@example.test',(select v from data where k='association-selection'))$$,'23514',null,'Fresh schema5 requires newly associated original provenance');
select * from finish();rollback;
